"use client"

import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { Tabs as TabsPrimitive } from "radix-ui"

import { useInk, useMergedRef } from "@/lib/ink/react"
import { tabsTriggerRecipe } from "@/lib/ink/recipes/tabs-ink"
import { cn } from "@/lib/utils"

const TabsContext = React.createContext<{ variant: "default" | "line" }>({ variant: "line" })

function Tabs({ className, ...props }: React.ComponentProps<typeof TabsPrimitive.Root>) {
  return (
    <TabsPrimitive.Root data-slot="tabs" className={cn("flex flex-col gap-4", className)} {...props} />
  )
}

const tabsListVariants = cva("inline-flex h-10 w-fit items-end justify-center gap-1 text-muted-foreground", {
  variants: {
    variant: {
      default: "rounded-[var(--radius-md)] bg-[color-mix(in_srgb,var(--sd-sand-shade)_35%,transparent)] p-1",
      line: "border-b border-[var(--sd-line-soft)] pb-0",
    },
  },
  defaultVariants: { variant: "line" },
})

function TabsList({
  className,
  variant = "line",
  ...props
}: React.ComponentProps<typeof TabsPrimitive.List> & VariantProps<typeof tabsListVariants>) {
  const v = variant ?? "line"
  return (
    <TabsContext.Provider value={{ variant: v }}>
      <TabsPrimitive.List data-slot="tabs-list" data-variant={v} className={cn(tabsListVariants({ variant: v }), className)} {...props} />
    </TabsContext.Provider>
  )
}

function TabsTrigger({
  className,
  seed,
  disabled,
  ref,
  children,
  ...props
}: React.ComponentProps<typeof TabsPrimitive.Trigger> & { seed?: string | number }) {
  const { variant } = React.useContext(TabsContext)
  const { hostRef, hostProps, node } = useInk({
    recipe: tabsTriggerRecipe,
    params: { variant, disabled: !!disabled },
    kind: "tab",
    seed,
    still: true,
  })
  const mergedRef = useMergedRef<HTMLButtonElement>(hostRef, ref)

  return (
    <TabsPrimitive.Trigger
      data-slot="tabs-trigger"
      ref={mergedRef}
      {...hostProps}
      disabled={disabled}
      className={cn(
        "relative isolate inline-flex h-9 flex-1 items-center justify-center gap-1.5 px-4 text-sm font-medium whitespace-nowrap",
        "text-muted-foreground transition-colors hover:text-foreground data-[state=active]:text-foreground",
        "disabled:pointer-events-none disabled:opacity-60 focus-visible:outline-none",
        className,
      )}
      {...props}
    >
      {node}
      <span className="relative z-[1]">{children}</span>
    </TabsPrimitive.Trigger>
  )
}

function TabsContent({ className, ...props }: React.ComponentProps<typeof TabsPrimitive.Content>) {
  return (
    <TabsPrimitive.Content
      data-slot="tabs-content"
      className={cn("text-sm outline-none focus-visible:ring-2 focus-visible:ring-[var(--sd-focus)]", className)}
      {...props}
    />
  )
}

export { Tabs, TabsContent, TabsList, TabsTrigger }

import { wash } from '@/lib/ink/fills'
import { roundRectPoly } from '@/lib/ink/geom'
import { focusRing, line, underline } from '@/lib/ink/shapes'
import { defineRecipe } from '@/lib/ink/recipes'

export interface TabsTriggerParams {
  variant?: 'default' | 'line'
  disabled?: boolean
}

export const tabsTriggerRecipe = defineRecipe<TabsTriggerParams>({
  id: 'tabs',
  kind: 'tab',
  layers: ['rest', 'hover', 'checked', 'focus', 'disabled'],
  lazy: ['focus'],
  pad: 8,
  draw(ink, { w, h }, { variant = 'line', disabled }, ctx) {
    const baseline = h - 1.4
    const strip = roundRectPoly(2, h - 5, w - 4, 4, 2)

    if (disabled) {
      if (ctx.lazyOnly) return
      ink.layer('disabled', () => {
        line(ink, 3, baseline, w - 3, baseline, { pen: 'pencil.fine', opts: { alpha: 0.3, simple: true } })
      })
      return
    }

    ctx.lazy('focus', (fink) => {
      wash(fink, strip, 'star', { alpha: 0.15, material: 'wash', wobble: 0.5 })
      focusRing(fink, 0, 0, w, h, { r: 4, pen: 'horizonPencil.fine', opts: { alpha: 0.75, simple: true } })
    })
    if (ctx.lazyOnly) return

    ink.layer('rest', () => {
      if (variant === 'default') {
        wash(ink, roundRectPoly(1, 1, w - 2, h - 2, 4), 'sand-slip', { alpha: 0.35, material: 'wash', wobble: 0.45 })
      }
      line(ink, 2, baseline, w - 2, baseline, {
        pen: 'pencil.fine',
        opts: { alpha: 0.38, simple: true, color: 'line-soft' },
      })
    })

    ink.layer('hover', () => {
      wash(ink, strip, 'rose-wash', { alpha: 0.35, material: 'wash', wobble: 0.85 })
      line(ink, 4, baseline, w - 4, baseline, {
        pen: 'horizonPencil.fine',
        opts: { alpha: 0.55, simple: true },
      })
    })

    ink.layer('checked', () => {
      ink.part('swipe', () => {
        wash(ink, strip, 'rose-wash', { alpha: 0.5, material: 'wash', wobble: 0.9 })
        wash(ink, strip, 'horizon', { alpha: 0.18, material: 'wash', inset: 0.3 })
        underline(ink, 3, baseline, w - 6, { pen: 'rose.fine', kind: 'single', opts: { alpha: 0.85 } })
        underline(ink, 2, baseline + 0.8, w - 4, {
          pen: 'horizon.brush',
          kind: 'single',
          opts: { alpha: 0.45 },
        })
      })
    })
  },
})

import type { Ink } from '@/lib/ink/builder'
import type { Pt } from '@/lib/ink/types'
import type { PaintKey } from '@/lib/ink/paint'
import { wash } from '@/lib/ink/fills'

export function softFill(
  ink: Ink,
  body: Pt[],
  layers: Array<{ color: PaintKey; alpha: number; inset?: number; wobble?: number }>,
) {
  for (const layer of layers) {
    wash(ink, body, layer.color, {
      alpha: layer.alpha,
      inset: layer.inset ?? 0.4,
      wobble: layer.wobble ?? 0.95,
      material: 'wash',
    })
  }
}
